from math import gcd
from fractions import Fraction
from collections import deque

def solve_mean_problem_fast(m, n, max_steps=6):
    """
    Simulates the process of generating means from m/n and n/m to check if 1 can be reached.
    Uses a stricter max_steps limit for faster execution.
    """
    if m == n:
        return (False, None)

    start_frac1 = Fraction(m, n)
    start_frac2 = Fraction(n, m)

    if start_frac1 == 1 or start_frac2 == 1:
        return (True, 0)

    dist = {start_frac1: 0, start_frac2: 0}
    new_additions = deque([start_frac1, start_frac2]) # Queue for newly generated elements in the current step

    # BFS level tracking
    step = 0

    while step < max_steps:
        next_additions = deque()

        # We iterate over all pairs found so far (those in dist)
        current_reachable = list(dist.keys())

        # Check all combinations of pairs (x, y) from current_reachable
        for i in range(len(current_reachable)):
            x = current_reachable[i]
            d_x = dist[x]

            for j in range(i, len(current_reachable)): # Check (x, x) and (x, y)
                y = current_reachable[j]
                d_y = dist[y]

                # Skip combination with itself if we strictly only look for new pairs, 
                # but (x, x) always yields x, so we can skip it.
                if x == y and i == j:
                    continue

                # The step count for the mean is max(d_x, d_y) + 1
                new_dist = max(d_x, d_y) + 1

                # Arithmetic Mean: (x + y) / 2
                am = (x + y) / 2

                # Harmonic Mean: 2xy / (x + y)
                if x + y != 0:
                    hm = (2 * x * y) / (x + y)
                else:
                    continue

                for new_val in [am, hm]:
                    if new_val == Fraction(1):
                        return (True, new_dist) 

                    # Only update if the fraction hasn't been reached before.
                    if new_val not in dist:
                        dist[new_val] = new_dist
                        next_additions.append(new_val)

        # Move to the next step
        step += 1
        # Append all newly discovered fractions to the general pool for the next iteration
        new_additions.extend(list(next_additions))

    return (False, None)


